const T = aide.THREE;
const BALL_R = 0.02;
const HOLE_R = 0.045;
const START = new T.Vector3(0, 0.031, 0.12);
const HOLE = new T.Vector3(0, 0.012, -0.32);
const FW = { w: 0.28, len: 0.7, cz: -0.1 };

aide.say('Pinch near the white ball, drag gently, and flick to putt into the far hole.');

let strokes = 0;
let best = 0;
let holding = false;
let holdHand = null;
let holed = false;
let holeTimer = -1;
let doneCalled = false;

const greenMat = new T.MeshStandardMaterial({ color: '#2e8b4a', roughness: 0.9 });
const green = new T.Mesh(new T.BoxGeometry(FW.w, 0.012, FW.len), greenMat);
green.position.set(0, 0.006, FW.cz);
aide.scene.add(green);

const fringe = new T.Mesh(new T.BoxGeometry(FW.w + 0.04, 0.006, FW.len + 0.04),
  new T.MeshStandardMaterial({ color: '#1d5c30', roughness: 0.9 }));
fringe.position.set(0, 0.003, FW.cz);
aide.scene.add(fringe);

const holeMesh = new T.Mesh(new T.CylinderGeometry(HOLE_R, HOLE_R, 0.014, 28),
  new T.MeshStandardMaterial({ color: '#0a0a0a', roughness: 1 }));
holeMesh.position.copy(HOLE);
aide.scene.add(holeMesh);
const rim = new T.Mesh(new T.RingGeometry(HOLE_R, HOLE_R + 0.008, 28),
  new T.MeshStandardMaterial({ color: '#ffffff', roughness: 0.6, side: T.DoubleSide }));
rim.rotation.x = -Math.PI / 2;
rim.position.set(HOLE.x, 0.0135, HOLE.z);
aide.scene.add(rim);

const wallMat = new T.MeshStandardMaterial({ color: '#8a5a2b', roughness: 0.7 });
function addWall(x, z, sx, sz) {
  const m = new T.Mesh(new T.BoxGeometry(sx, 0.05, sz), wallMat);
  m.position.set(x, 0.025, z);
  aide.scene.add(m);
  aide.physics.add(m, { shape: 'box', size: [sx, 0.05, sz], mass: 0, isStatic: true, bounce: 0.6, friction: 0.2 });
  return m;
}
const hw = FW.w / 2 + 0.01;
addWall(-hw, FW.cz, 0.02, FW.len + 0.04);
addWall(hw, FW.cz, 0.02, FW.len + 0.04);
addWall(0, FW.cz - FW.len / 2 - 0.01, FW.w + 0.06, 0.02);
addWall(0, FW.cz + FW.len / 2 + 0.01, FW.w + 0.06, 0.02);

const ball = aide.spawn('ball', { radius: BALL_R, color: '#ffffff', position: [START.x, START.y, START.z], physics: { mass: 0.05, bounce: 0.45, friction: 0.6 } });

const strokeLabel = aide.spawn('label', { text: 'Strokes: 0', size: 0.03, position: [-0.12, 0.22, -0.1] });
const bestLabel = aide.spawn('label', { text: 'Best: -', size: 0.028, position: [0.13, 0.22, -0.1] });
const hintLabel = aide.spawn('label', { text: 'Pinch ball to putt', size: 0.025, position: [0, 0.15, 0.12] });

const panel = aide.panel({
  title: 'Table Mini-Golf',
  text: 'Putt into the far hole. Fewest strokes wins.',
  buttons: [{ id: 'reset', label: 'Reset ball' }, { id: 'again', label: 'Restart game' }],
  onButton: (id) => {
    if (id === 'reset') resetBall(false);
    if (id === 'again') restart();
  }
});

function resetBall(silent) {
  if (holed) return;
  ball.position.copy(START);
  if (ball.body) { ball.body.velocity.set(0, 0, 0); ball.body.angularVelocity.set(0, 0, 0); ball.body.isStatic = false; }
  holding = false; holdHand = null;
  if (!silent) aide.sound.pop();
}
function restart() {
  strokes = 0;
  holed = false;
  holeTimer = -1;
  strokeLabel.setText('Strokes: 0');
  hintLabel.setText('Pinch ball to putt');
  ball.position.copy(START);
  if (ball.body) { ball.body.velocity.set(0, 0, 0); ball.body.isStatic = false; }
  holding = false; holdHand = null;
  aide.sound.pop();
}

const tmpV = new T.Vector3();

aide.onPinch((e) => {
  if (holed || holding) return;
  const d = e.point.distanceTo(ball.position);
  if (d < 0.09) {
    holding = true;
    holdHand = e.hand;
    if (ball.body) { ball.body.velocity.set(0, 0, 0); ball.body.isStatic = true; }
    aide.sound.tick();
    hintLabel.setText('Flick to putt, release');
  }
});

function clampToFairway(p) {
  const minX = -FW.w / 2 + BALL_R + 0.005;
  const maxX = FW.w / 2 - BALL_R - 0.005;
  const minZ = FW.cz - FW.len / 2 + BALL_R;
  const maxZ = FW.cz + FW.len / 2 - BALL_R;
  p.x = Math.max(minX, Math.min(maxX, p.x));
  p.z = Math.max(minZ, Math.min(maxZ, p.z));
  p.y = 0.012 + BALL_R;
}

aide.onFrame((dt, t) => {
  if (holding) {
    const h = aide.hands[holdHand];
    if (!h.visible || !h.pinching) {
      const v = h.visible ? h.velocity : tmpV.set(0, 0, 0);
      tmpV.copy(v);
      tmpV.y = 0;
      const sp = tmpV.length();
      if (ball.body) ball.body.isStatic = false;
      holding = false;
      if (sp > 0.25) {
        if (sp > 2.5) tmpV.multiplyScalar(2.5 / sp);
        if (ball.body) ball.body.velocity.copy(tmpV);
        strokes += 1;
        strokeLabel.setText('Strokes: ' + strokes);
        aide.score(strokes);
        aide.sound.pop();
        hintLabel.setText('Nice! ' + strokes + (strokes === 1 ? ' stroke' : ' strokes'));
      } else {
        if (ball.body) ball.body.isStatic = false;
        hintLabel.setText('Flick a bit harder');
      }
      holdHand = null;
    } else {
      tmpV.copy(h.pinchPoint);
      clampToFairway(tmpV);
      ball.position.copy(tmpV);
      if (ball.body) ball.body.velocity.set(0, 0, 0);
    }
    return;
  }

  if (!holed && ball.body && !ball.body.isStatic) {
    if (Math.abs(ball.position.x) > 0.5 || Math.abs(ball.position.z) > 0.55 || ball.position.y < -0.05) {
      resetBall(false);
      hintLabel.setText('Kept on fairway');
      return;
    }
    const dx = ball.position.x - HOLE.x;
    const dz = ball.position.z - HOLE.z;
    const dist = Math.sqrt(dx * dx + dz * dz);
    const speed = ball.body.velocity.length();
    if (dist < HOLE_R + 0.008 && ball.position.y < 0.06 && speed < 1.6) {
      holed = true;
      holeTimer = 5.0;
      ball.body.velocity.set(0, 0, 0);
      ball.body.isStatic = true;
      ball.position.set(HOLE.x, 0.02, HOLE.z);
      if (best === 0 || strokes < best) best = strokes;
      bestLabel.setText('Best: ' + best);
      strokeLabel.setText('Holed in ' + strokes + '!');
      hintLabel.setText(strokes <= 2 ? 'Amazing putt!' : strokes <= 4 ? 'Holed! Great!' : 'Holed! Play again?');
      aide.spawn('burst', { position: [HOLE.x, 0.06, HOLE.z], color: '#ffd400', count: 32 });
      aide.sound.score();
      aide.sound.chime();
      aide.score(strokes);
      aide.say(strokes <= 2 ? 'Wow, holed in ' + strokes + '!' : 'Holed in ' + strokes + ' strokes!');
      return;
    }
    if (ball.body.velocity.length() < 0.02) {
      ball.body.velocity.set(0, 0, 0);
    }
  }

  if (holed && holeTimer > 0 && !doneCalled) {
    holeTimer -= dt;
    const pulse = 1 + Math.sin(t * 6) * 0.06;
    rim.scale.set(pulse, pulse, 1);
    if (holeTimer <= 0) {
      doneCalled = true;
      panel.close();
      aide.done('mini-golf holed in ' + strokes + ' strokes, best ' + best);
    }
  }
});
